export const COMMIT_TX = "import NonFungibleToken from 0xNonFungible\nimport FlovatarComponent from 0xFlovatar\nimport FlovatarUniverseBuilder from 0xFUB\n\n// CREATOR: Commit = burn 1..30 TerraKit FUB vouchers -> new FUB (status \"building\") bound PERMANENTLY to one of your\n// islands that hosts no FUB yet (the FUB building goes on it now and stays with the island). Creates the Studio on first use.\ntransaction(voucherIds: [UInt64], name: String, islandId: UInt64) {\n    let vouchers: @[FlovatarComponent.NFT]\n    let studio: auth(FlovatarUniverseBuilder.Owner) &FlovatarUniverseBuilder.Studio\n    prepare(signer: auth(Storage) &Account) {\n        if signer.storage.type(at: FlovatarUniverseBuilder.StudioStoragePath) == nil {\n            signer.storage.save(<-FlovatarUniverseBuilder.createStudio(), to: FlovatarUniverseBuilder.StudioStoragePath)\n        }\n        self.studio = signer.storage.borrow<auth(FlovatarUniverseBuilder.Owner) &FlovatarUniverseBuilder.Studio>(from: FlovatarUniverseBuilder.StudioStoragePath)!\n        let col = signer.storage.borrow<auth(NonFungibleToken.Withdraw) &FlovatarComponent.Collection>(from: FlovatarComponent.CollectionStoragePath)\n            ?? panic(\"No Flobit collection\")\n        self.vouchers <- []\n        for id in voucherIds {\n            self.vouchers.append(<-(col.withdraw(withdrawID: id) as! @FlovatarComponent.NFT))\n        }\n    }\n    execute {\n        FlovatarUniverseBuilder.commit(vouchers: <-self.vouchers, studio: self.studio, name: name, islandId: islandId)\n    }\n}\n";
export const ABSORB_TX = "import NonFungibleToken from 0xNonFungible\nimport FlovatarComponent from 0xFlovatar\nimport FlovatarUniverseBuilder from 0xFUB\n\n// CREATOR: merge more FUB vouchers into a FUB that is still building (max 30 per FUB, never after publish).\ntransaction(fubId: UInt64, voucherIds: [UInt64]) {\n    let vouchers: @[FlovatarComponent.NFT]\n    let studio: auth(FlovatarUniverseBuilder.Owner) &FlovatarUniverseBuilder.Studio\n    prepare(signer: auth(BorrowValue) &Account) {\n        self.studio = signer.storage.borrow<auth(FlovatarUniverseBuilder.Owner) &FlovatarUniverseBuilder.Studio>(from: FlovatarUniverseBuilder.StudioStoragePath)\n            ?? panic(\"No FUB studio in this account\")\n        let col = signer.storage.borrow<auth(NonFungibleToken.Withdraw) &FlovatarComponent.Collection>(from: FlovatarComponent.CollectionStoragePath)\n            ?? panic(\"No Flobit collection\")\n        self.vouchers <- []\n        for id in voucherIds { self.vouchers.append(<-(col.withdraw(withdrawID: id) as! @FlovatarComponent.NFT)) }\n    }\n    execute {\n        self.studio.absorb(fubId: fubId, vouchers: <-self.vouchers)\n    }\n}\n";
