export const MINT_TX = "import FungibleToken from 0xFungible\nimport NonFungibleToken from 0xNonFungible\nimport FlovatarDustToken from 0xFlovatar\nimport FlovatarUniverseBuilder from 0xFUB\n\n// BUYER: mint a F.U.N. Pays at most maxPrice \u0110UST (the curve may move between quote and seal); change returns.\ntransaction(fubId: UInt64, layerKeys: [String], itemIds: [UInt64], maxPrice: UFix64) {\n    let payment: @{FungibleToken.Vault}\n    let vault: auth(FungibleToken.Withdraw) &FlovatarDustToken.Vault\n    let receiver: &{NonFungibleToken.Receiver}\n    prepare(signer: auth(Storage, Capabilities) &Account) {\n        assert(layerKeys.length == itemIds.length, message: \"length mismatch\")\n        if signer.storage.type(at: FlovatarUniverseBuilder.CollectionStoragePath) == nil {\n            signer.storage.save(<-FlovatarUniverseBuilder.createEmptyCollection(nftType: Type<@FlovatarUniverseBuilder.NFT>()), to: FlovatarUniverseBuilder.CollectionStoragePath)\n            signer.capabilities.unpublish(FlovatarUniverseBuilder.CollectionPublicPath)\n            signer.capabilities.publish(signer.capabilities.storage.issue<&FlovatarUniverseBuilder.Collection>(FlovatarUniverseBuilder.CollectionStoragePath), at: FlovatarUniverseBuilder.CollectionPublicPath)\n        }\n        self.receiver = signer.storage.borrow<&FlovatarUniverseBuilder.Collection>(from: FlovatarUniverseBuilder.CollectionStoragePath)!\n        self.vault = signer.storage.borrow<auth(FungibleToken.Withdraw) &FlovatarDustToken.Vault>(from: FlovatarDustToken.VaultStoragePath)\n            ?? panic(\"No \u0110UST vault\")\n        self.payment <- self.vault.withdraw(amount: maxPrice)\n    }\n    execute {\n        let picks: {String: UInt64} = {}\n        var i = 0\n        while i < layerKeys.length { picks[layerKeys[i]] = itemIds[i]; i = i + 1 }\n        let change <- FlovatarUniverseBuilder.mint(fubId: fubId, picks: picks, payment: <-self.payment, maxPrice: maxPrice, recipient: self.receiver)\n        self.vault.deposit(from: <-change)\n    }\n}\n";
export const REFILL_TANK_TX = "import FungibleToken from 0xFungible\nimport FlovatarDustToken from 0xFlovatar\nimport FlovatarUniverseBuilder from 0xFUB\n\n// Refill the design-assistant tank: BURNS the \u0110UST (any amount within the settings tankMin..tankMax) and emits TankRefilled for the signer.\ntransaction(amount: UFix64, ref: String) {\n    let payment: @{FungibleToken.Vault}\n    let account: Address\n    prepare(signer: auth(BorrowValue) &Account) {\n        let v = signer.storage.borrow<auth(FungibleToken.Withdraw) &FlovatarDustToken.Vault>(from: FlovatarDustToken.VaultStoragePath) ?? panic(\"No \u0110UST vault\")\n        self.payment <- v.withdraw(amount: amount)\n        self.account = signer.address\n    }\n    execute {\n        FlovatarUniverseBuilder.refillTank(payment: <-self.payment, account: self.account, ref: ref)\n    }\n}\n";
export const REFILL_TANK_FLOW_TX = "import FungibleToken from 0xFungible\nimport FlowToken from 0xFlowToken\nimport FlovatarDustToken from 0xFlovatar\nimport FlovatarUniverseBuilder from 0xFUB\nimport SwapRouter from 0xSwapRouter\nimport SwapConfig from 0xSwapConfig\n\n// Refill the design-assistant tank PAYING FLOW, in one transaction: withdraw at most maxFlowIn FLOW (spendable FLOW only,\n// never the storage reserve), swap it on the Increment \u0110UST/FLOW pool for EXACTLY `amount` \u0110UST, burn that \u0110UST into the\n// tank (refillTank: same TankRefilled + TokensBurned as a \u0110UST refill) and return the unused FLOW. Reverts when the swap\n// would need more than maxFlowIn (slippage, EXCESSIVE_INPUT_AMOUNT) or after `deadline` (unix seconds).\ntransaction(amount: UFix64, maxFlowIn: UFix64, deadline: UFix64, ref: String) {\n    let payment: @{FungibleToken.Vault}\n    let account: Address\n    prepare(signer: auth(BorrowValue) &Account) {\n        assert(maxFlowIn <= signer.availableBalance, message: \"Not enough FLOW (the storage reserve can't be spent)\")\n        let flowVault = signer.storage.borrow<auth(FungibleToken.Withdraw) &FlowToken.Vault>(from: /storage/flowTokenVault)\n            ?? panic(\"No FLOW vault\")\n        let flowKey = SwapConfig.SliceTokenTypeIdentifierFromVaultType(vaultTypeIdentifier: Type<@FlowToken.Vault>().identifier)\n        let dustKey = SwapConfig.SliceTokenTypeIdentifierFromVaultType(vaultTypeIdentifier: Type<@FlovatarDustToken.Vault>().identifier)\n        let vaults <- SwapRouter.swapTokensForExactTokens(\n            vaultInMax: <-flowVault.withdraw(amount: maxFlowIn),\n            exactAmountOut: amount,\n            tokenKeyPath: [flowKey, dustKey],\n            deadline: deadline\n        )\n        let leftover <- vaults.removeLast()\n        let swapped <- vaults.removeLast()\n        destroy vaults\n        flowVault.deposit(from: <-leftover)\n        assert(swapped.balance >= amount, message: \"The swap returned less \u0110UST than the refill amount\")\n        self.payment <- swapped.withdraw(amount: amount)\n        // exact-output swap: nothing should be left; any rounding extra goes to the signer's \u0110UST vault\n        if let mine = signer.storage.borrow<&FlovatarDustToken.Vault>(from: FlovatarDustToken.VaultStoragePath) {\n            mine.deposit(from: <-swapped)\n        } else {\n            assert(swapped.balance == 0.0, message: \"No \u0110UST vault for the swap remainder\")\n            destroy swapped\n        }\n        self.account = signer.address\n    }\n    execute {\n        FlovatarUniverseBuilder.refillTank(payment: <-self.payment, account: self.account, ref: ref)\n    }\n}\n";
export const SETUP_COLLECTION_TX = "import NonFungibleToken from 0xNonFungible\nimport FlovatarUniverseBuilder from 0xFUB\n\n// Sets up the F.U.N. collection (idempotent).\ntransaction {\n    prepare(signer: auth(Storage, Capabilities) &Account) {\n        if signer.storage.type(at: FlovatarUniverseBuilder.CollectionStoragePath) == nil {\n            signer.storage.save(<-FlovatarUniverseBuilder.createEmptyCollection(nftType: Type<@FlovatarUniverseBuilder.NFT>()), to: FlovatarUniverseBuilder.CollectionStoragePath)\n            signer.capabilities.unpublish(FlovatarUniverseBuilder.CollectionPublicPath)\n            signer.capabilities.publish(signer.capabilities.storage.issue<&FlovatarUniverseBuilder.Collection>(FlovatarUniverseBuilder.CollectionStoragePath), at: FlovatarUniverseBuilder.CollectionPublicPath)\n        }\n    }\n}\n";
export const WALLET_FUB_SCRIPT = "import FlovatarComponent from 0xFlovatar\nimport FlovatarComponentTemplate from 0xFlovatar\nimport FlovatarUniverseBuilder from 0xFUB\nimport FlovatarAsteroidIsland from 0xIslands\n\n// For the web studio: the wallet's usable FUB vouchers by rarity, its FUB ids, islands without a FUB (freeIslands) and\n// every island with its FUB state (islands: id, rarity, name, free, reason hosts-fub|no-building, fubId), F.U.N. collection.\naccess(all) fun main(address: Address): {String: AnyStruct} {\n    let acct = getAccount(address)\n    let vouchers: {String: [UInt64]} = {}\n    // voucher id -> component template id (the web shows each voucher's illustration)\n    let voucherTemplates: {UInt64: UInt64} = {}\n    if let col = acct.capabilities.borrow<&{FlovatarComponent.CollectionPublic}>(FlovatarComponent.CollectionPublicPath) {\n        for id in col.getIDs() {\n            if let c = col.borrowComponent(id: id) {\n                if let t = FlovatarComponentTemplate.getComponentTemplate(id: c.templateId) {\n                    if t.category == FlovatarUniverseBuilder.setting(\"voucherCategory\") && t.series.toString() == FlovatarUniverseBuilder.setting(\"voucherSeries\")\n                        && !FlovatarComponentTemplate.isRestricted(nftType: Type<@FlovatarComponent.NFT>(), id: id, owner: address) {\n                        let l = vouchers[t.rarity] ?? []\n                        l.append(id)\n                        vouchers[t.rarity] = l\n                        voucherTemplates[id] = c.templateId\n                    }\n                }\n            }\n        }\n    }\n    let fubs: [UInt64] = []\n    var i: UInt64 = 1\n    while i <= FlovatarUniverseBuilder.fubCount {\n        if let f = FlovatarUniverseBuilder.getFub(i) { if f.creator == address { fubs.append(i) } }\n        i = i + 1\n    }\n    let islands: {UInt64: String} = {}\n    // every island with its FUB state, so the commit step can show taken islands disabled with the reason\n    let islandList: [{String: AnyStruct}] = []\n    if let ic = acct.capabilities.borrow<&{FlovatarAsteroidIsland.CollectionPublic}>(FlovatarAsteroidIsland.CollectionPublicPath) {\n        for id in ic.getIDs() {\n            if let isl = ic.borrowIsland(id: id) {\n                let fubId = FlovatarUniverseBuilder.getIslandFub(islandId: id)\n                var reason = \"\"\n                if fubId != nil { reason = \"hosts-fub\" }\n                else if isl.hostsFub() { reason = \"hosts-fub\" }\n                else if FlovatarAsteroidIsland.setting(\"fubBuilding.\".concat(isl.rarity)) == \"\" { reason = \"no-building\" }\n                if reason == \"\" { islands[id] = isl.rarity }\n                islandList.append({\"id\": id, \"rarity\": isl.rarity, \"name\": isl.displayName(), \"free\": reason == \"\", \"reason\": reason, \"fubId\": fubId})\n            }\n        }\n    }\n    return {\n        \"vouchers\": vouchers,\n        \"voucherTemplates\": voucherTemplates,\n        \"fubs\": fubs,\n        \"freeIslands\": islands,\n        \"islands\": islandList,\n        \"funCollection\": acct.capabilities.borrow<&{FlovatarUniverseBuilder.CollectionPublic}>(FlovatarUniverseBuilder.CollectionPublicPath) != nil\n    }\n}\n";
